const path = require('path')
const { CLIEngine } = require('eslint')

class PrettierEslint {
  constructor() {
    this.root = path.normalize(__dirname + '/../../..')
    this.modules = path.normalize(__dirname + '/../..')
    this.loadConfig()
    this.loadCLI()
    this.loadPlugins()
  }

  loadConfig() {
    const configFile = this.getModule('.eslintrc', true)

    this.rules = configFile ? configFile.rules : {}

    if (configFile && configFile.extends) {
      let baseConfig = this.getModule('eslint-config-' + configFile.extends)

      if (baseConfig) {
        this.plugins = [...baseConfig.plugins]
        delete baseConfig.plugins
      }

      this.baseConfig = baseConfig
    } else {
      this.baseConfig = {
        extends: 'eslint:recommended'
      }
    }
  }

  loadCLI() {
    this.cli = new CLIEngine({
      fix: true,
      useEslintrc: false,
      rules: this.rules,
      baseConfig: this.baseConfig
    })
  }

  loadPlugins() {
    if (this.plugins) {
      this.plugins.forEach(plugin => {
        this.cli.addPlugin(plugin, this.getModule('eslint-plugin-' + plugin))
      })
    }
  }

  getModule(module, root = false) {
    try {
      return root ? require(this.root + '/' + module) : require(this.modules + '/' + module)
    } catch (e) {
      return null
    }
  }

  process(text, options) {
    const report = this.cli.executeOnText(text, options.filepath)
    const [{ output = text }] = report.results

    return output
  }
}

module.exports = PrettierEslint
